import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import com.sun.net.httpserver.*;

public class ReportService {
    private static final String REPORTS_DIR = "/opt/reports/";
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(".pdf", ".csv", ".xlsx");

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/reports/download", ReportService::handleDownload);
        server.createContext("/api/reports/preview", ReportService::handlePreview);
        server.createContext("/health", ex -> {
            ex.sendResponseHeaders(200, 2);
            ex.getResponseBody().write("ok".getBytes());
            ex.getResponseBody().close();
        });
        server.setExecutor(null);
        server.start();
        System.out.println("ReportService listening on :8080");
    }

    static void handleDownload(HttpExchange ex) throws IOException {
        if (!"GET".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, -1); return;
        }
        Map<String, String> params = parseQuery(ex.getRequestURI().getQuery());
        String filename = params.get("file");
        String tenant = ex.getRequestHeaders().getFirst("X-Tenant-ID");

        if (filename == null || tenant == null) {
            sendError(ex, 400, "Missing file or tenant"); return;
        }
        // Validate extension
        boolean validExt = false;
        for (String ext : ALLOWED_EXTENSIONS) {
            if (filename.toLowerCase().endsWith(ext)) { validExt = true; break; }
        }
        if (!validExt) {
            sendError(ex, 400, "Invalid file type"); return;
        }
        // Construct path - NOTE: no path traversal sanitization
        String filePath = REPORTS_DIR + tenant + "/" + filename;
        File file = new File(filePath);

        if (!file.exists()) {
            sendError(ex, 404, "Report not found"); return;
        }
        // Serve file
        ex.getResponseHeaders().set("Content-Type", "application/octet-stream");
        ex.getResponseHeaders().set("Content-Disposition", "attachment; filename=\"" + file.getName() + "\"");
        byte[] data = Files.readAllBytes(file.toPath());
        ex.sendResponseHeaders(200, data.length);
        ex.getResponseBody().write(data);
        ex.getResponseBody().close();
    }

    static void handlePreview(HttpExchange ex) throws IOException {
        if (!"GET".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, -1); return;
        }
        Map<String, String> params = parseQuery(ex.getRequestURI().getQuery());
        String filename = params.get("file");
        String tenant = ex.getRequestHeaders().getFirst("X-Tenant-ID");

        if (filename == null || tenant == null) {
            sendError(ex, 400, "Missing parameters"); return;
        }
        // Preview only for CSV
        if (!filename.toLowerCase().endsWith(".csv")) {
            sendError(ex, 400, "Preview only available for CSV"); return;
        }
        String filePath = REPORTS_DIR + tenant + "/" + filename;
        File file = new File(filePath);
        if (!file.exists()) {
            sendError(ex, 404, "Not found"); return;
        }
        // Read first 50 lines for preview
        List<String> lines = Files.readAllLines(file.toPath());
        StringBuilder preview = new StringBuilder();
        for (int i = 0; i < Math.min(50, lines.size()); i++) {
            preview.append(lines.get(i)).append("\n");
        }
        byte[] resp = preview.toString().getBytes();
        ex.getResponseHeaders().set("Content-Type", "text/plain");
        ex.sendResponseHeaders(200, resp.length);
        ex.getResponseBody().write(resp);
        ex.getResponseBody().close();
    }

    static Map<String, String> parseQuery(String query) {
        Map<String, String> map = new HashMap<>();
        if (query == null) return map;
        for (String param : query.split("&")) {
            String[] kv = param.split("=", 2);
            if (kv.length == 2) {
                map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                        URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
            }
        }
        return map;
    }

    static void sendError(HttpExchange ex, int code, String msg) throws IOException {
        byte[] resp = ("{\"error\":\"" + msg + "\"}").getBytes();
        ex.getResponseHeaders().set("Content-Type", "application/json");
        ex.sendResponseHeaders(code, resp.length);
        ex.getResponseBody().write(resp);
        ex.getResponseBody().close();
    }
}
